export function receiveGrantA2ASources(index, sectionText) {
  need(index && typeof index === 'object' && Array.isArray(index.sources), 'Use the original reviewer source index.');
  need(typeof sectionText === 'string', 'Pass the original customer parser selected A2A section.');
  if (!sectionText.trim()) return index;
  const sources = index.sources.map(source => ({ ...source }));
  const selected = CHAPTER_SOURCES.map(spec => chapterSelection(sectionText, spec)).filter(Boolean);
  if (!selected.length) return index;
  const ownedIds = new Set(CHAPTER_SOURCES.map(source => source.id));
  for (const source of sources) if (ownedIds.has(source.id)) reconcileBytes(source);
  for (const source of selected) replaceSource(sources, source);
  for (const source of RETAINED_SOURCES) replaceSource(sources, source, { immutable: true });
