  if (sdk?.commit === '29417a5bb4038f804f310ce4fffd267a9375aa90') sdk.declared_package_version = '1.3.0';
  else if (sdk?.declared_package_version === '1.3.0') delete sdk.declared_package_version;
  const original = index.narrative_source?.composition?.a2a_source_catalogue || {};
