    selected_chapter_source_ids: selected.map(item => item.id),
    retained_source_ids: [...new Set([...(original.retained_source_ids || []), ...RETAINED_SOURCES.map(item => item.id)])],
    observations, scope: 'Selected source identities and individually dated source-transfer evidence. Execution and settlement remain with their original result sources.' };
